<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — 500-Step NLP Demo</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;background:#f6f7fb;color:#111827}.page{width:min(1180px,calc(100% - 28px));margin:30px auto 70px}.hero{text-align:center;padding:28px 15px}.badge{display:inline-flex;padding:7px 12px;border-radius:99px;background:#eeecff;color:#6556ef;font-size:11px;font-weight:900}.hero h1{font-size:clamp(34px,6vw,62px);letter-spacing:-3px;margin:14px 0 9px}.hero h1 span{color:#6d5dfc}.hero p{max-width:760px;margin:auto;color:#687386;line-height:1.7;font-size:14px}.stats{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin:20px 0}.stat{background:#fff;border:1px solid #e4e7ef;border-radius:13px;padding:10px 15px;font-size:11px}.stat b{font-size:17px;display:block;color:#5d4fe2}.box{background:#fff;border:1px solid #e4e7ef;border-radius:24px;padding:22px;box-shadow:0 20px 60px rgba(30,35,70,.08)}textarea{width:100%;min-height:130px;border:1px solid #dfe3ec;border-radius:16px;padding:17px;font:15px/1.6 inherit;resize:vertical;outline:none}.examples{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.example{border:1px solid #e4e6ed;background:#fafbfe;border-radius:99px;padding:7px 10px;font-size:11px;cursor:pointer}.run{margin-top:8px;width:100%;border:0;border-radius:14px;padding:14px;background:linear-gradient(135deg,#6556ef,#927cff);color:#fff;font-size:14px;font-weight:900;cursor:pointer}.result{display:none;margin-top:18px}.result.show{display:block}.grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:14px}.panel{border:1px solid #e5e7ef;border-radius:17px;padding:17px;background:#fafbff}.panel h3{margin:0 0 13px;font-size:13px}.intent{display:inline-flex;padding:7px 10px;border-radius:99px;background:#eceaff;color:#5d4fe2;font-size:11px;font-weight:900}.confidence{margin-top:13px;font-size:11px;color:#697488}.bar{height:7px;background:#e8eaf0;border-radius:99px;margin-top:6px;overflow:hidden}.bar i{display:block;width:0;height:100%;background:#7566fa}.chips{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.chip{font-size:10px;padding:6px 8px;background:#fff;border:1px solid #e5e7ef;border-radius:99px}.notice{margin-top:14px;padding:12px;border-radius:12px;background:#f3f1ff;color:#5548ca;font-size:11px;line-height:1.6}.step{display:flex;align-items:center;gap:10px;padding:11px;border-radius:12px;background:#fff;border:1px solid #e8e9ef;margin-top:8px}.num{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;background:#eeecff;color:#6556ef;font-weight:900;font-size:10px;flex:0 0 auto}.step b{font-size:12px}.step small{display:block;color:#7d8798;font-size:10px;margin-top:2px}.engine{margin-top:14px;border:1px solid #e5e7ef;border-radius:17px;padding:15px;background:#fff}.engine-head{display:flex;justify-content:space-between;gap:10px;align-items:center}.engine-head b{font-size:12px}.search{font-size:10px;color:#7b8495}.catalog{margin-top:10px;display:grid;grid-template-columns:repeat(5,1fr);gap:5px;max-height:180px;overflow:auto}.action{padding:7px;border:1px solid #e7e8ee;border-radius:9px;background:#fafbfe;font-size:9px}.action strong{display:block;color:#5d4fe2;font-size:9px}@media(max-width:800px){.grid{grid-template-columns:1fr}.catalog{grid-template-columns:repeat(2,1fr)}}</style></head><body><main class="page"><section class="hero"><span class="badge">🧠 500-STEP NLP ENGINE • FREE DEMO</span><h1>Tell SmartToolz what you<br><span>want to get done.</span></h1><p>Type one request and the engine extracts intent, entities, parameters and a multi-step plan from a 500-action library.</p><div class="stats"><div class="stat"><b>500</b>NLP actions</div><div class="stat"><b>50</b>task families</div><div class="stat"><b>12</b>workflow steps</div><div class="stat"><b>0</b>paid AI APIs</div></div></section><section class="box"><textarea id="prompt" placeholder="Example: Resize 50 product images to 1200px, compress them, convert to WebP, rename them for SEO and package everything into a ZIP..."></textarea><div class="examples"><button class="example">Resize 50 product images to 1200px, compress, WebP, SEO rename and ZIP</button><button class="example">Merge these PDFs, compress the result and make every page a JPG</button><button class="example">Clean this CSV, remove duplicates, sort it and export JSON</button><button class="example">Create a QR code, add a logo and prepare it for download</button></div><button class="run" id="run">✨ Understand Request & Build Workflow</button><div class="result" id="result"><div class="grid"><div class="panel"><h3>🧠 NLP UNDERSTANDING</h3><span class="intent" id="intent">Waiting for request</span><div class="confidence">Intent confidence: <b id="conf">—</b><div class="bar"><i id="bar"></i></div></div><div class="chips" id="chips"></div><div class="notice" id="explain">The demo uses a deterministic 500-action intent library. No paid AI API is required.</div></div><div class="panel"><h3>⚡ GENERATED WORKFLOW</h3><div id="steps"></div></div></div><div class="engine"><div class="engine-head"><b>⚙️ NLP ACTION LIBRARY — <span id="count">500</span> / 500 LOADED</b><span class="search">Live catalog preview</span></div><div class="catalog" id="catalog"></div></div></div></section></main><script>
const p=document.getElementById('prompt'),r=document.getElementById('result'),steps=document.getElementById('steps'),intent=document.getElementById('intent'),explain=document.getElementById('explain'),chips=document.getElementById('chips'),conf=document.getElementById('conf'),bar=document.getElementById('bar');
const families=[['Image','resize','compress','crop','rotate','flip','jpg','png','webp','gif','watermark'],['PDF','merge','split','compress','jpg','png','text','protect','extract','organize','convert'],['Text','word','case','slug','spaces','sort','reverse','duplicate','markdown','encode'],['Developer','json','base64','url','html','uuid','timestamp','regex','minify','validate'],['QR','qr','read','generate','scan','decode','logo','style','size','download'],['Data','csv','clean','dedupe','sort','filter','columns','json','xml','export'],['Video','gif','frames','trim','resize','compress','convert','extract','thumbnail','caption'],['Audio','trim','convert','compress','normalize','metadata','waveform','extract','merge','split'],['SEO','title','meta','slug','keywords','alt','schema','sitemap','robots','canonical'],['Utility','age','percentage','bmi','unit','number','timer','stopwatch','lorem','random'],['Security','password','hash','token','uuid','encode','decode','validate','sanitize','mask'],['Web','html','css','js','url','link','redirect','favicon','manifest','compress'],['Files','rename','zip','unzip','batch','organize','sort','filter','copy','package'],['Automation','workflow','batch','queue','schedule','trigger','chain','condition','retry','notify'],['Content','summarize','rewrite','translate','extract','outline','headline','caption','proofread','paraphrase'],['Images AI','background','remove','enhance','upscale','denoise','sharpen','blur','mask','object','quality'],['Business','invoice','quote','report','table','budget','percentage','currency','forecast','summary'],['Learning','lesson','quiz','flashcard','summary','notes','outline','practice','explain','translate'],['Marketing','campaign','caption','hashtags','ad','email','landing','product','social','calendar'],['Database','sql','query','format','validate','schema','json','csv','export','import'],['Email','compose','subject','template','signature','format','extract','clean','html','plain'],['Documents','doc','text','extract','format','merge','split','convert','compress','template'],['Accessibility','alt','contrast','text','caption','transcript','heading','label','aria','readability'],['Design','color','picker','palette','gradient','hex','rgb','hsl','contrast','convert'],['Analytics','event','utm','csv','json','summary','filter','sort','report','export'],['Commerce','product','image','sku','price','csv','feed','description','variant','inventory'],['DevOps','log','json','yaml','env','config','validate','format','diff','backup'],['API','url','json','request','response','headers','token','encode','decode','validate'],['Knowledge','extract','summarize','classify','compare','outline','answer','keyword','translate','notes'],['Workflow','plan','chain','branch','condition','loop','batch','parallel','retry','approval'],['Storage','upload','download','zip','folder','rename','move','copy','delete','package'],['Localization','translate','locale','currency','date','number','timezone','language','format','plural'],['Images Batch','resize','compress','webp','jpg','png','rename','crop','rotate','watermark'],['PDF Batch','merge','split','compress','jpg','png','rename','extract','zip','protect','export'],['Text Batch','clean','case','slug','dedupe','sort','reverse','spaces','format','export'],['Data Batch','clean','dedupe','sort','filter','map','join','split','convert','validate'],['QA','validate','test','compare','diff','check','scan','audit','report','fix'],['Conversion','jpg','png','webp','pdf','text','json','csv','xml','html'],['Optimization','compress','resize','minify','dedupe','cache','quality','format','convert','clean'],['Privacy','remove','metadata','mask','redact','sanitize','anonymize','hash','delete','export'],['Productivity','todo','notes','summary','template','checklist','rename','organize','batch','schedule'],['Social','caption','hashtags','image','resize','compress','webp','thumbnail','copy','calendar'],['Publishing','markdown','html','pdf','image','compress','slug','meta','title','export'],['Research','search','extract','summarize','compare','classify','keywords','outline','notes','export'],['Finance','percentage','currency','invoice','budget','tax','profit','loss','forecast','table'],['Education','explain','quiz','summary','flashcards','notes','outline','practice','grade','translate'],['Monitoring','status','health','check','log','report','alert','threshold','schedule','export'],['Notifications','email','webhook','notify','template','schedule','trigger','condition','retry','log'],['Packaging','zip','rename','organize','manifest','checksum','compress','batch','package','download'],['Advanced','chain','branch','loop','parallel','condition','parameter','entity','intent','confidence','execute']];
const actions=[];families.forEach(f=>f.slice(1,11).forEach(v=>actions.push({id:actions.length+1,family:f[0],verb:v,name:f[0]+' '+v.charAt(0).toUpperCase()+v.slice(1)})));
const keywords={resize:['resize','size','px','pixel','dimension'],compress:['compress','smaller','reduce size','optimize'],crop:['crop','cut'],rotate:['rotate','turn'],flip:['flip','mirror'],webp:['webp'],jpg:['jpg','jpeg'],png:['png'],gif:['gif'],qr:['qr','qrcode'],json:['json'],csv:['csv'],pdf:['pdf'],merge:['merge','combine'],split:['split','separate'],rename:['rename','filename','file name'],zip:['zip','archive','package'],slug:['slug','seo friendly','seo-friendly'],dedupe:['duplicate','dedupe','remove duplicates'],sort:['sort','order','ascending','descending'],base64:['base64'],url:['url','link'],html:['html'],markdown:['markdown','md'],uuid:['uuid'],timestamp:['timestamp','unix time'],password:['password','passcode'],translate:['translate','translation'],summarize:['summarize','summary'],extract:['extract','get text'],caption:['caption'],watermark:['watermark','logo'],background:['background'],upscale:['upscale','resolution'],alt:['alt text'],meta:['meta description'],schema:['schema'],percentage:['percentage','percent','%'],unit:['unit','convert'],timer:['timer'],stopwatch:['stopwatch'],invoice:['invoice'],budget:['budget'],sql:['sql','query'],yaml:['yaml'],regex:['regex'],validate:['validate','validation','check'],format:['format','beautify','pretty'],clean:['clean','cleanup'],filter:['filter'],export:['export','save as'],batch:['batch','many','100','50','bulk'],schedule:['schedule','later','recurring'],workflow:['workflow','automate'],condition:['if ','when ','unless'],retry:['retry'],notify:['notify','alert'],hashtags:['hashtags','tags'],product:['product','products'],thumbnail:['thumbnail'],audio:['audio','sound'],video:['video'],frames:['frames'],trim:['trim'],scan:['scan','read'],decode:['decode'],encode:['encode'],hash:['hash','checksum'],sanitize:['sanitize'],redact:['redact'],anonymize:['anonymize'],compare:['compare','difference','diff'],outline:['outline'],quiz:['quiz','questions'],notes:['notes'],flashcard:['flashcard'],proofread:['proofread','grammar'],paraphrase:['paraphrase','rewrite'],classify:['classify','categorize']};
const has=(text,arr)=>arr.some(k=>text.includes(k));
function analyze(raw){const s=raw.toLowerCase(),hits=[];actions.forEach(a=>{if(has(s,keywords[a.verb]||[a.verb]))hits.push(a)});const counts={};hits.forEach(a=>counts[a.family]=(counts[a.family]||0)+1);const family=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'General Workflow';const plan=[];const add=(verb,name,desc,icon)=>{const a=actions.find(x=>x.verb===verb);if(a&&!plan.some(x=>x.verb===verb))plan.push({verb,name:name||a.name,desc,icon:icon||'⚙️'})};
if(has(s,keywords.resize))add('resize','Resize Images','Apply requested dimensions.','📐');if(has(s,keywords.compress))add('compress','Compress Files','Reduce size while preserving useful quality.','⚡');if(has(s,keywords.webp))add('webp','Convert to WebP','Create optimized WebP output.','🔄');else if(has(s,keywords.jpg))add('jpg','Convert to JPG','Create JPG output.','🖼️');if(has(s,keywords.rename)||has(s,['seo']))add('rename','SEO Rename','Generate clean descriptive filenames.','🏷️');if(has(s,keywords.crop))add('crop','Crop','Apply requested crop.','✂️');if(has(s,keywords.rotate))add('rotate','Rotate','Apply requested rotation.','↻');if(has(s,keywords.watermark))add('watermark','Watermark','Apply logo or watermark.','💧');if(has(s,keywords.merge))add('merge','Merge Files','Combine inputs into one output.','🔗');if(has(s,keywords.split))add('split','Split Files','Separate the input into parts.','✂️');if(has(s,keywords.json))add('json','Format JSON','Validate and beautify JSON.','{ }');if(has(s,keywords.csv))add('csv','Process CSV','Clean and transform tabular data.','📊');if(has(s,keywords.dedupe))add('dedupe','Remove Duplicates','Remove duplicate records or lines.','🧹');if(has(s,keywords.sort))add('sort','Sort Data','Sort using the requested order.','↕️');if(has(s,keywords.zip)||has(s,['package','archive']))add('zip','Create ZIP','Package outputs into an archive.','📦');if(has(s,keywords.qr))add('qr','Create QR Code','Generate a QR code.','📱');if(has(s,keywords.translate))add('translate','Translate','Translate supplied content.','🌐');if(has(s,keywords.summarize))add('summarize','Summarize','Create a concise summary.','📝');if(has(s,keywords.extract))add('extract','Extract Content','Extract useful content from the input.','🔎');if(has(s,keywords.validate))add('validate','Validate','Check input for errors.','✅');if(has(s,keywords.format))add('format','Format','Apply clean formatting.','✨');if(has(s,keywords.batch)||/\b\d+\s*(images?|files?|photos?|pdfs?)/.test(s))add('batch','Batch Process','Process multiple inputs together.','🗂️');if(!plan.length)plan.push({verb:'workflow',name:'Analyze Request',desc:'Select the best SmartToolz actions for this request.','icon':'🧠'});return {family,plan,matched:hits}}
function renderCatalog(){document.getElementById('catalog').innerHTML=actions.map(a=>`<div class="action"><strong>#${a.id} ${a.family}</strong>${String(a.name).replace(a.family+' ','')}</div>`).join('');document.getElementById('count').textContent=actions.length}
document.querySelectorAll('.example').forEach(b=>b.onclick=()=>p.value=b.textContent);document.getElementById('run').onclick=()=>{const v=p.value.trim();if(!v){p.focus();return}const a=analyze(v);intent.textContent=a.family+' workflow';const score=Math.min(99,Math.max(72,78+a.plan.length*4+a.matched.length));conf.textContent=score+'%';bar.style.width=score+'%';chips.innerHTML=[...new Set(a.matched.map(x=>x.verb))].slice(0,14).map(x=>`<span class="chip">${x}</span>`).join('');steps.innerHTML=a.plan.slice(0,12).map((x,i)=>`<div class="step"><span class="num">${i+1}</span><span style="font-size:19px">${x.icon}</span><div><b>${x.name}</b><small>${x.desc}</small></div></div>`).join('');explain.textContent=`NLP detected ${a.matched.length} matching action signals and built ${a.plan.length} workflow steps from your request.`;r.classList.add('show');r.scrollIntoView({behavior:'smooth',block:'nearest'})};renderCatalog();
</script></body></html>